  "settings.modelProvider.fieldHelp": "{field} hakkında",
  "settings.modelProvider.help.contextWindow": "Modelin aynı anda işleyebileceği bağlam kapasitesi, token cinsinden. ZAICODE bunu bağlamı yönetmek için kullanır.\nModelin gerçek sınırını aşmayın.",
  "settings.modelProvider.help.maxOutputTokens": "Tek bir model isteğinin üretebileceği en fazla token sayısı.\nModelin gerçek sınırını aşmayın.",
  "settings.modelProvider.help.inputModalities": "Modelin alabileceği içerik türlerini ayarlayın:\n\n- **Metin**: Metin içeriği alır. Zorunlu.\n- **Görseller**: Görsel içerik alır.\n- **Video**: Video içerik alır.\n- **PDF**: PDF belgelerini doğrudan alır.",
  "settings.modelProvider.help.outputModalities": "Modelin yanıtlarının içerik türü. Şu anda yalnızca metin desteklenir.",
  "settings.modelProvider.help.capabilities": "- **Yapılandırılmış çıktı**: Çıktı alanları, türleri ve yapısı üzerinde JSON Schema kısıtlamalarını destekler.\n- **Yerel web araması**: Model API'sinin yerleşik web arama yeteneğini destekler.\n- **Konuşma ortasında sistem mesajları**: Konuşma sırasında sistem talimatları eklemeyi destekler.\n\nModelin desteklemediği yetenekleri etkinleştirmeyin.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Sohbette kullanılabilir akıl yürütme düzeylerini ayarlayın. **Düşükten yükseğe akıl yürütme düzeyine göre sıralanmalıdır**.\nModelin desteklemediği akıl yürütme düzeylerini yapılandırmayın.",
  "settings.modelProvider.help.reasoningLevelMapping": "Mevcut `reasoningLevel` akıl yürütme düzeyini model API istek alanlarına eşlemek için bir CEL ifadesi kullanın. İfade tarafından döndürülen JSON nesnesi giden istek gövdesiyle birleştirilir.",
  "settings.modelProvider.help.advanced": "**MFJS araç şeması**: Moonshot Flavored JSON Schema uyumluluğunu etkinleştirir, genellikle Moonshot'un Kimi model API'si tarafından kullanılır. Yalnızca model API'si bu biçimi gerektirdiğinde etkinleştirin.",
  "settings.modelProvider.help.followRecommendedConfig": "Model ID, Temel URL ve API biçimi kullanılarak önerilen yapılandırmayla eşleşir. ZAICODE önerileri sürekli günceller ve otomatik olarak size senkronize eder.\nBir ayarı elle değiştirdiğinizde, o ayar elle yönetilir hale gelir ve öneri güncellemelerini izlemeyi bırakır; diğer ayarlar akıllı yapılandırma tarafından yönetilmeye devam eder.",
