  "zaicode.help.step1": "1. Ajanlar ve Modlar (sol): Hunter, Tester, Cleaner, Wikier, Translator ve özel roller. Bir modu etkinleştirmek için tıklayın, sonra ajanı serbest bırakmak için kuyrukta görev atayın.",
