  "zaicode.help.step3": "3. Ayrıntılar (sağ): durumunu, hatasını, sonucunu görmek ve sohbet oturumunu açmak için bir göreve tıklayın. Parallel N aynı anda kaç tanesinin çalışacağını sınırlar.",
